"""Generate a persistent pytest suite from archived structured test cases."""

from __future__ import annotations

from collections.abc import Sequence

from restgen.core.representation.templates import Location
from restgen.core.representation.testcase import TestCase
from restgen.core.representation.values import ABSENT


def pytest_suite(cases: Sequence[TestCase]) -> str:
    tests = "\n\n".join(_test(index, case) for index, case in enumerate(cases))
    return f'''\
"""Generated by restgen DABC-HS. Re-run only through the measurement proxy."""
import json
import os
from urllib.parse import quote

import httpx

BASE_URL = os.environ["RESTGEN_BASE_URL"].rstrip("/")
HEADERS = json.loads(os.environ.get("RESTGEN_HEADERS", "{{}}"))
TIMEOUT = float(os.environ.get("RESTGEN_REQUEST_TIMEOUT", "10"))


def _value(value, responses):
    if isinstance(value, dict) and set(value) == {{"from_action", "path"}}:
        current = responses[value["from_action"]]
        path = value["path"]
        if path == "$":
            return current
        for part in path.removeprefix("$.").split("."):
            current = current[part]
        return current
    if isinstance(value, dict):
        return {{key: _value(item, responses) for key, item in value.items()}}
    if isinstance(value, list):
        return [_value(item, responses) for item in value]
    return value


def _call(method, path, query, headers, cookies, has_body, body, responses):
    values = {{key: _value(value, responses) for key, value in path.items()}}
    url_path = values.pop("__template__")
    for name, value in values.items():
        url_path = url_path.replace("{{" + name + "}}", quote(str(value), safe=""))
    arguments = {{
        "params": _value(query, responses),
        "headers": {{**HEADERS, **_value(headers, responses)}},
        "cookies": _value(cookies, responses),
        "timeout": TIMEOUT,
    }}
    if has_body:
        arguments["json"] = _value(body, responses)
    response = httpx.request(method, BASE_URL + url_path, **arguments)
    try:
        parsed = response.json() if response.content else None
    except ValueError:
        parsed = response.text
    responses.append(parsed)
    assert response.status_code < 500, response.text
    return response


{tests}
'''


def _test(index: int, case: TestCase) -> str:
    lines = [f"def test_dabc_hs_{index:04d}():", "    responses = []"]
    for action in case.actions:
        path_template = action.operation.base_path + action.operation.path
        path: dict[str, object] = {"__template__": path_template}
        query: dict[str, object] = {}
        headers: dict[str, object] = {}
        cookies: dict[str, object] = {}
        described = action.describe()
        for position in action.operation.inputs:
            if position.location is Location.BODY:
                continue
            value = described.get(position.key, ABSENT)
            if value is ABSENT:
                continue
            if position.location is Location.PATH:
                path[position.name] = value
            elif position.location is Location.QUERY:
                query[position.name] = value
            elif position.location is Location.HEADER:
                headers[position.name] = value
            elif position.location is Location.COOKIE:
                cookies[position.name] = value
        has_body = "body" in described
        body = described.get("body")
        arguments = [
            repr(action.operation.method),
            _literal(path),
            _literal(query),
            _literal(headers),
            _literal(cookies),
            repr(has_body),
            _literal(body),
            "responses",
        ]
        lines.append(f"    _call({', '.join(arguments)})")
    return "\n".join(lines)


def _literal(value: object) -> str:
    return repr(value)
